import { CommonModule } from '@angular/common';
import { Component, inject } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { CameraResultType } from '@capacitor/camera';
import {
  IonBackButton,
  IonButtons,
  IonContent,
  IonHeader,
  IonTitle,
  IonToolbar,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { menu, settings } from 'ionicons/icons';
import { BehaviorSubject, firstValueFrom, from, map, switchMap } from 'rxjs';
import { AlertService } from '../common/alert/alert.service';
import { CameraService } from '../common/camera/camera.service';
import { LoadingService } from '../common/loading/loading.service';
import { StorageService } from '../common/storage/storage.service';
import { UserService } from '../common/user/user.service';
import { AvatarComponent } from './avatar/avatar.component';
import { Profile } from './profile';
import { ProfileService } from './profile.service';
import { getSearchRoutePath } from '../app.routes';
import { ProfileFormComponent } from './form/profile-form.component';

export type ProfileForm = Omit<Profile, 'id' | 'updated_at' | 'avatar_url' | 'username'>;

@Component({
    selector: 'app-profile',
    templateUrl: './profile.page.html',
    styleUrls: ['./profile.page.scss'],
    imports: [
        IonButtons,
        IonBackButton,
        IonHeader,
        IonContent,
        IonToolbar,
        IonTitle,
        ReactiveFormsModule,
        CommonModule,
        AvatarComponent,
        ProfileFormComponent,
    ]
})
export class ProfilePage {
  private alertService = inject(AlertService);
  private cameraService = inject(CameraService);
  private loadingService = inject(LoadingService);
  private storageService = inject(StorageService);
  private userService = inject(UserService);
  private profileService = inject(ProfileService);

  readonly defaultHref = getSearchRoutePath();

  // Trigger for refreshing profile data
  private refreshTrigger$ = new BehaviorSubject<void>(undefined);

  // Reactive streams for profile data
  profile$ = this.refreshTrigger$.pipe(
    switchMap(() => from(this.profileService.getProfile())),
    map(response => response.data || this.getEmptyProfile())
  );
  
  email$ = from(this.userService.getUser()).pipe(
    map(user => user?.email || '')
  );

  avatar$ = this.profile$.pipe(
    map(profile => profile.avatar_url)
  );

  constructor() {
    addIcons({ settings, menu });
  }

  async handleAvatarClicked() {
    try {
      const fileNameNoExt = `${Math.random()}-${new Date().getTime()}`;
      const { file, name } = await this.cameraService.getPhoto(fileNameNoExt, {
        resultType: CameraResultType.DataUrl,
      });

      this.loadingService.setLoading(true);

      await this.storageService.upload('avatars', name, file);

      const currentProfile = await firstValueFrom(this.profile$);
      const updatedProfile = { ...currentProfile, avatar_url: name };
      await this.profileService.updateProfile(updatedProfile);
      
      // Trigger refresh of profile data
      this.refreshTrigger$.next();
      
      await this.alertService.createNotice({
        message: 'Avatar updated!',
        duration: 5000,
        positionAnchor: 'footer',
      });
    } catch (error: unknown) {
      const message = (error as Error).message || 'Unknown error';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
        color: 'danger',
      });
    } finally {
      this.loadingService.setLoading(false);
    }
  }

  async onSubmit(profileForm: ProfileForm) {
    try {
      this.loadingService.setLoading(true);
      
      const currentProfile = await firstValueFrom(this.profile$);
      const updatedProfile = { ...currentProfile, ...profileForm };
      
      await this.profileService.updateProfile(updatedProfile);
      
      // Trigger refresh of profile data
      this.refreshTrigger$.next();
      
      await this.alertService.createNotice({
        message: 'Profile updated!',
        duration: 5000,
        positionAnchor: 'footer',
      });
    } catch (error: unknown) {
      const message = (error as Error).message || 'Failed to update profile';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
        color: 'danger',
      });
    } finally {
      this.loadingService.setLoading(false);
    }
  }

  // Helper method for updating profile fields from template
  updateProfileField(field: keyof ProfileForm, value: string) {
    // This will be used in the template for two-way binding
    const profileForm: Partial<ProfileForm> = { [field]: value };
    // We'll handle this reactively in the template
  }

  private getEmptyProfile(): Profile {
    return {
      username: '',
      avatar_url: '',
      website: '',
      full_name: '',
      id: '',
      updated_at: '',
    };
  }
}
