import { Injectable } from '@angular/core';

import { Camera, ImageOptions } from '@capacitor/camera';

@Injectable({
  providedIn: 'root',
})
export class CameraService {
  async getPhoto(fileNameNoExt: string, opts: ImageOptions) {
    const photo = await Camera.getPhoto(opts);
    const name = `${fileNameNoExt}.${photo.format}`;
    const response = await fetch(photo.dataUrl!);
    const file = await response.blob();
    return { file, name };
  }
}

// The iOS implementation of File is wonky but this seems to work
export type iOSSafeFile = {
  name: string;
  file: Blob;
};
