import { Component, EventEmitter, Input, Output } from '@angular/core';
import {
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import {
  IonButton,
  IonInput,
  IonItem,
  IonLabel,
} from '@ionic/angular/standalone';
import { Profile } from '../profile';
import { ProfileForm } from '../profile.page';

type ProfileFormControls = {
  email: FormControl<string>;
  full_name: FormControl<string>;
  website: FormControl<string>;
};

@Component({
  selector: 'app-profile-form',
  imports: [IonButton, IonInput, IonItem, IonLabel, ReactiveFormsModule],
  templateUrl: './profile-form.component.html',
  styleUrls: ['./profile-form.component.scss'],
})
export class ProfileFormComponent {
  private emailValue: string = '';

  @Input() set profile(value: Profile | null) {
    if (!value) {
      return;
    }
    this.formGroup.patchValue(this.createProfileFormValue(value));
  }

  @Input() set email(value: string | null) {
    if (value) {
      this.emailValue = value;
      this.formGroup.patchValue({ email: value });
    }
  }

  @Output() formSubmitted = new EventEmitter<ProfileForm>();

  formGroup = this.createProfileForm();

  onSubmit() {
    if (!this.formGroup.valid) {
      return;
    }
    this.formSubmitted.emit({
      full_name: this.formGroup.value.full_name || '',
      website: this.formGroup.value.website || '',
    });
  }

  private createProfileForm() {
    return new FormGroup<ProfileFormControls>({
      email: new FormControl('', {
        nonNullable: true,
        validators: [Validators.required, Validators.email],
      }),
      full_name: new FormControl('', {
        nonNullable: true,
        validators: [Validators.required],
      }),
      website: new FormControl('', { nonNullable: true }),
    });
  }

  private createProfileFormValue(profile: Profile) {
    return {
      email: this.emailValue, // Use the stored email value
      full_name: profile.full_name || '',
      website: profile.website || '',
    };
  }
}
